insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_24'), (select id from public.groups where slug = 'evangelion' and site_id = 'anime'), 'Gainax, Khara and Netflix: Evangelion Behind the Screens', 'gainax-khara-and-netflix-evangelion-behind-the-screens', 'multiple_choice', '[{"question":"Who co-directed The End of Evangelion with Hideaki Anno?","options":["Hayao Miyazaki","Kazuya Tsurumaki","Satoshi Kon","Mamoru Oshii"],"correct":1,"kind":"production","spoiler":{"arc":4,"scope":"anime"},"fact_ids":["evangelion-end-of-evangelion-film-008"],"source_url":"https://en.wikipedia.org/wiki/The_End_of_Evangelion"},{"question":"Which studio made The End of Evangelion together with Gainax?","options":["Madhouse","Production I.G","Bones","Studio Khara"],"correct":1,"kind":"production","spoiler":{"arc":4,"scope":"anime"},"fact_ids":["evangelion-end-of-evangelion-film-008"],"source_url":"https://en.wikipedia.org/wiki/The_End_of_Evangelion"},{"question":"On which date did The End of Evangelion reach Japanese cinemas?","options":["October 4, 1995","March 27, 1996","June 21, 2019","July 19, 1997"],"correct":3,"kind":"production","spoiler":{"arc":4,"scope":"anime"},"fact_ids":["evangelion-end-of-evangelion-film-008"],"source_url":"https://en.wikipedia.org/wiki/The_End_of_Evangelion"},{"question":"Which studio made the Rebuild of Evangelion films?","options":["Studio Khara","Gainax","Tatsunoko Production","Production I.G"],"correct":0,"kind":"production","spoiler":{"arc":5,"scope":"anime"},"fact_ids":["evangelion-rebuild-films-009"],"source_url":"https://en.wikipedia.org/wiki/Rebuild_of_Evangelion"},{"question":"How many Rebuild of Evangelion films are there?","options":["Two","Three","Four","Six"],"correct":2,"kind":"production","spoiler":{"arc":5,"scope":"anime"},"fact_ids":["evangelion-rebuild-films-009"]