insert into public.quizzes (creator_id, group_id, title, slug, quiz_type, questions, difficulty, status, question_count, site_id, spoiler_arc_ord, spoiler_scope) values ((select id from public.profiles where username = 'oq_creator_16'), (select id from public.groups where slug = 'haikyu' and site_id = 'anime'), 'Crows on Court: Who Plays Where?', 'crows-on-court-who-plays-where', 'multiple_choice', '[{"question":"Which nickname belongs to the small ace on TV who inspires Hinata to join Karasuno?","options":["The Tiny Crow","The Mini Ace","The Little Giant","The Short Wall"],"correct":2,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["haikyu-hinata-little-giant-018"],"source_url":"https://en.wikipedia.org/wiki/Haikyu!!"},{"question":"Which award show gave Hinata Best Boy at its fifth edition?","options":["Crunchyroll Anime Awards","Tokyo Anime Award","Seiyu Awards","Japan Media Arts Festival"],"correct":0,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["haikyu-hinata-best-boy-019"],"source_url":"https://en.wikipedia.org/wiki/Haikyu!!"},{"question":"Which Karasuno player is the setter?","options":["Kei Tsukishima","Tobio Kageyama","Tadashi Yamaguchi","Asahi Azumane"],"correct":1,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["haikyu-tobio-kageyama-name-022","haikyu-kei-tsukishima-name-023","haikyu-tadashi-yamaguchi-name-024","haikyu-asahi-azumane-name-027"],"source_url":"https://en.wikipedia.org/wiki/List_of_Haikyu!!_characters"},{"question":"Which Karasuno player is the middle blocker?","options":["Asahi Azumane","Kei Tsukishima","Daichi Sawamura","Ryūnosuke Tanaka"],"correct":1,"kind":"character","spoiler":{"arc":0,"scope":"both"},"fact_ids":["haikyu-kei-tsukishima-name-023","haikyu-daichi-sawamura-name-025","haikyu-asahi-azumane-name-027","haikyu-ryunosuke-tanaka-name-029"],"source_url":"https://en.wikipedia.org/wiki/List_of_Haikyu!!_characters"},{"question":"Which Karasuno player is the serving specialist?","o